def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    aggressive_count = 0
    desperate_count = 0
    rich_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 300:
                rich_count += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if bid >= 100:
                    aggressive_count += 1

    if budget <= 0:
        return 0.0

    if not alive:
        return max(0.0, min(budget, 12.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (25.0 - supply) / 10.0
    scarcity = max(0.0, min(1.0, scarcity))

    life_urgency = 0.0
    if hp <= 2:
        life_urgency += 1.0
    elif hp <= 4:
        life_urgency += 0.55
    if no_water_days >= 2:
        life_urgency += 1.0
    elif no_water_days >= 1:
        life_urgency += 0.45

    base = 18.0
    if supply >= 22:
        base = 10.0
    elif supply >= 19:
        base = 14.0
    elif supply >= 17:
        base = 20.0
    else:
        base = 28.0

    pressure_bid = 0.0
    if highest_prev > 0:
        if highest_prev >= 120:
            pressure_bid = 16.0 + 6.0 * scarcity
        elif highest_prev >= 70:
            pressure_bid = min(55.0, highest_prev * 0.55 + 3.0)
        else:
            pressure_bid = max(base, highest_prev + 2.0)

    bid = max(base, pressure_bid)

    if aggressive_count >= 2 and supply >= 20 and life_urgency < 0.8:
        bid = min(bid, 12.0)

    if rich_count >= 2 and avg_prev >= 100 and supply >= 19 and life_urgency < 0.8:
        bid = min(bid, 10.0)

    if desperate_count >= 1 and supply <= 17:
        bid = max(bid, 32.0)

    if life_urgency >= 1.5:
        bid = max(bid, 62.0)
    elif life_urgency >= 0.8:
        bid = max(bid, 42.0)

    if day >= 8 and hp >= 6 and no_water_days == 0 and supply >= 20:
        bid = min(bid, 9.0)

    reserve_floor = 0.0
    if hp > 2:
        reserve_floor = 20.0
    if budget <= reserve_floor:
        bid = min(bid, budget)
    else:
        bid = min(bid, budget - reserve_floor + min(reserve_floor, 5.0))

    bid = max(0.0, min(budget, bid))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    if not alive:
        return float(min(my_budget, DAILY_SALARY * 0.4))

    # Inspect yesterday bids from immediate previous_trace only
    yesterday_bids = []
    for oid, o in alive:
        prev = o.get('previous_trace', {})
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    # Estimate how many water units are likely available (approx)
    # supply is float; ensure integer indices if needed
    supply_int = int(round(float(supply)))
    # Determine aggressiveness target based on opponent pressure
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # Cindy-like behavior: high bids that correlate with survival
        # If someone bid very high, we must contest; otherwise, bid enough to stay competitive.
        if highest_prev_bid >= DAILY_SALARY * 1.35:
            base = DAILY_SALARY * 0.95
        elif highest_prev_bid >= DAILY_SALARY * 0.9:
            base = DAILY_SALARY * 0.75
        else:
            base = DAILY_SALARY * 0.6
    else:
        base = DAILY_SALARY * 0.6

    # Adjust based on my current HP / no-water streak
    if my_hp <= 2:
        base = DAILY_SALARY * 0.98
    elif my_hp <= 4:
        base = max(base, DAILY_SALARY * 0.85)
    else:
        # If doing well, slightly reduce to preserve budget for later days
        base = min(base, DAILY_SALARY * 0.8)

    if my_no_water_days >= 2:
        base = max(base, DAILY_SALARY * 0.9)

    # Supply-based scaling: with more supply, we can bid less; with less, bid more
    if supply_int <= MIN_SUPPLY:
        base = max(base, DAILY_SALARY * 0.85)
    elif supply_int >= MAX_SUPPLY:
        base = min(base, DAILY_SALARY * 0.7)

    # Final cap by budget and ensure non-negative
    bid = float(max(0.0, min(my_budget, base)))

    # Small strategic nudge to beat Cindy when she likely overbids
    # Use yesterday highest bid as a reference, but don't overspend.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If we can afford a small overtake, do it; otherwise keep base.
        nudge = min(10.0, max(0.0, highest_prev_bid * 0.08))
        bid = float(min(my_budget, max(bid, highest_prev_bid + nudge * 0.2)))

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    most_aggressive_bid = 0.0
    aggressive_opponent_id = None

    for opp_id, opp_data in opponents_status.items():
        if opp_data['alive']:
            prev_trace = opp_data.get('previous_trace', {})
            if prev_trace and prev_trace.get('bid') is not None:
                if prev_trace['bid'] > most_aggressive_bid:
                    most_aggressive_bid = prev_trace['bid']
                    aggressive_opponent_id = opp_id

    base_bid = DAILY_SALARY * 0.6

    if aggressive_opponent_id:
        opp_water_req = opponents_status[aggressive_opponent_id]['water_requirement']

        # Check if supply is tight (not enough for both agents to get their full requirement)
        if day_context['supply'] < (WATER_REQ + opp_water_req):
            # Direct competition, bid aggressively
            if my_status['hp'] <= 3: # Critical HP
                base_bid = max(most_aggressive_bid * 1.05, DAILY_SALARY * 0.95)
            elif my_status['hp'] <= 6: # Low HP
                base_bid = max(most_aggressive_bid * 1.03, DAILY_SALARY * 0.85)
            else: # Healthy HP
                base_bid = max(most_aggressive_bid * 1.01, DAILY_SALARY * 0.75)
        else:
            # Supply is more abundant, can be slightly less aggressive
            if my_status['hp'] <= 3: # Critical HP, still bid high to be safe
                base_bid = max(most_aggressive_bid * 0.95, DAILY_SALARY * 0.85)
            else: # Healthy HP, try to save budget
                base_bid = max(most_aggressive_bid * 0.8, DAILY_SALARY * 0.65)

    final_bid = min(my_status['budget'], base_bid)

    # Emergency bid if very low HP and not the last day, or if it's the last day
    if my_status['hp'] <= 1 and my_status['budget'] > 0 and day_context['day'] < EPISODE_DAYS:
        final_bid = my_status['budget'] * 0.99
    elif day_context['day'] == EPISODE_DAYS and my_status['hp'] > 0: 
        final_bid = min(my_status['budget'], DAILY_SALARY * 0.99)

    if final_bid < 1.0 and my_status['budget'] >= 1.0 and my_status['hp'] < 10:
        final_bid = 1.0

    return final_bid

